contracts/CardSVGGenerator.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

import "@openzeppelin/contracts/utils/Strings.sol";
import "@openzeppelin/contracts/utils/Base64.sol";

/**
 * @title CardSVGGenerator
 * @author Tejaswini Kunkulagunta (CS23B032)
 * @notice Generates high-fidelity on-chain SVG artwork and dynamic achievement badges
 *         reflecting real-world cricket athletic milestones.
 */
contract CardSVGGenerator {
    using Strings for uint256;
    using Strings for uint32;

    struct CardVisualParams {
        string name;
        string role;
        string team;
        uint8 rarity;
        uint16 multiplierBps;
        uint32 matches;
        uint32 runs;
        uint32 wickets;
        uint32 strikeRate;
        uint32 economy;
    }

    /**
     * @notice Returns hex color scheme for a given rarity tier
     */
    function getRarityColors(uint8 rarity) public pure returns (string memory primary, string memory border, string memory glow) {
        if (rarity == 4) {
            // Legendary (Amber / Gold)
            return ("#F59E0B", "#FBBF24", "rgba(245, 158, 11, 0.45)");
        } else if (rarity == 3) {
            // Epic (Purple / Violet)
            return ("#8B5CF6", "#A78BFA", "rgba(139, 92, 246, 0.45)");
        } else if (rarity == 2) {
            // Rare (Cyan / Electric Blue)
            return ("#0EA5E9", "#38BDF8", "rgba(14, 165, 233, 0.45)");
        } else if (rarity == 1) {
            // Uncommon (Emerald Turf Green)
            return ("#10B981", "#34D399", "rgba(16, 185, 129, 0.45)");
        } else {
            // Common (Steel / Slate)
            return ("#64748B", "#94A3B8", "rgba(100, 116, 139, 0.35)");
        }
    }

    /**
     * @notice Generates dynamic milestone achievement badges based on player telemetry
     */
    function generateBadges(uint32 runs, uint32 wickets, uint32 strikeRate, uint32 economy) public pure returns (string memory) {
        bytes memory b = "";

        if (runs >= 100) {
            b = abi.encodePacked(b, '<rect x="24" y="380" width="105" height="24" rx="12" fill="#FEF08A" stroke="#CA8A04" stroke-width="1.5"/><text x="76" y="396" fill="#854D0E" font-size="11" font-weight="bold" font-family="Arial, sans-serif" text-anchor="middle">CENTURION 100+</text>');
        } else if (runs >= 50) {
            b = abi.encodePacked(b, '<rect x="24" y="380" width="95" height="24" rx="12" fill="#FEF9C3" stroke="#EAB308" stroke-width="1.5"/><text x="71" y="396" fill="#A16207" font-size="11" font-weight="bold" font-family="Arial, sans-serif" text-anchor="middle">HALF-TON 50+</text>');
        }

        if (wickets >= 5) {
            b = abi.encodePacked(b, '<rect x="135" y="380" width="115" height="24" rx="12" fill="#FEE2E2" stroke="#DC2626" stroke-width="1.5"/><text x="192" y="396" fill="#991B1B" font-size="11" font-weight="bold" font-family="Arial, sans-serif" text-anchor="middle">5-WKT HAUL</text>');
        } else if (wickets >= 3) {
            b = abi.encodePacked(b, '<rect x="135" y="380" width="105" height="24" rx="12" fill="#FFEDD5" stroke="#EA580C" stroke-width="1.5"/><text x="187" y="396" fill="#9A3412" font-size="11" font-weight="bold" font-family="Arial, sans-serif" text-anchor="middle">3-WKT CRUSH</text>');
        }

        if (strikeRate >= 15000) {
            b = abi.encodePacked(b, '<rect x="24" y="412" width="110" height="22" rx="11" fill="#E0E7FF" stroke="#4F46E5" stroke-width="1"/><text x="79" y="427" fill="#3730A3" font-size="10" font-weight="bold" font-family="Arial, sans-serif" text-anchor="middle">STRIKE MASTER</text>');
        }

        if (economy > 0 && economy <= 600) {
            b = abi.encodePacked(b, '<rect x="140" y="412" width="105" height="22" rx="11" fill="#DCFCE7" stroke="#16A34A" stroke-width="1"/><text x="192" y="427" fill="#166534" font-size="10" font-weight="bold" font-family="Arial, sans-serif" text-anchor="middle">ECONOMY KING</text>');
        }

        return string(b);
    }

    /**
     * @notice Formats strike rate / economy with two decimal places
     */
    function formatScaled(uint32 val) public pure returns (string memory) {
        uint32 whole = val / 100;
        uint32 decimal = val % 100;
        string memory decStr = decimal < 10 ? string(abi.encodePacked("0", uint256(decimal).toString())) : uint256(decimal).toString();
        return string(abi.encodePacked(uint256(whole).toString(), ".", decStr));
    }

    function _renderHeader(string memory name, string memory role, string memory team, string memory primary, string memory border, string memory multStr) internal pure returns (bytes memory) {
        return abi.encodePacked(
            '<rect x="24" y="24" width="292" height="60" rx="14" fill="#0B1329" stroke="', border, '" stroke-width="1"/>',
            '<text x="38" y="52" fill="#F8FAFC" font-size="18" font-weight="900" font-family="Arial, sans-serif">', name, '</text>',
            '<text x="38" y="72" fill="', primary, '" font-size="12" font-weight="bold" font-family="Arial, sans-serif">', role, ' | ', team, '</text>',
            '<rect x="236" y="34" width="70" height="26" rx="8" fill="', primary, '"/>',
            '<text x="271" y="52" fill="#FFFFFF" font-size="12" font-weight="900" font-family="Arial, sans-serif" text-anchor="middle">', multStr, 'x</text>'
        );
    }

    function _renderStats(uint32 matches, uint32 runs, uint32 wickets, string memory srStr, string memory econStr) internal pure returns (bytes memory) {
        return abi.encodePacked(
            '<rect x="24" y="258" width="292" height="106" rx="14" fill="#0B1329" stroke="#334155" stroke-width="1"/>',
            '<text x="44" y="284" fill="#94A3B8" font-size="11" font-family="Arial, sans-serif">MATCHES</text>',
            '<text x="44" y="306" fill="#F8FAFC" font-size="16" font-weight="bold" font-family="Arial, sans-serif">', uint256(matches).toString(), '</text>',
            '<text x="120" y="284" fill="#94A3B8" font-size="11" font-family="Arial, sans-serif">RUNS</text>',
            '<text x="120" y="306" fill="#F8FAFC" font-size="16" font-weight="bold" font-family="Arial, sans-serif">', uint256(runs).toString(), '</text>',
            '<text x="194" y="284" fill="#94A3B8" font-size="11" font-family="Arial, sans-serif">WICKETS</text>',
            '<text x="194" y="306" fill="#F8FAFC" font-size="16" font-weight="bold" font-family="Arial, sans-serif">', uint256(wickets).toString(), '</text>',
            '<text x="260" y="284" fill="#94A3B8" font-size="11" font-family="Arial, sans-serif">STRIKE</text>',
            '<text x="260" y="306" fill="#F8FAFC" font-size="14" font-weight="bold" font-family="Arial, sans-serif">', srStr, '</text>',
            '<text x="44" y="336" fill="#94A3B8" font-size="11" font-family="Arial, sans-serif">ECONOMY: ', econStr, '</text>'
        );
    }

    /**
     * @notice Renders raw SVG XML string for a player card
     */
    function renderCardSVG(CardVisualParams memory p) public pure returns (string memory) {
        (string memory primary, string memory border, string memory glow) = getRarityColors(p.rarity);
        string memory badgeElements = generateBadges(p.runs, p.wickets, p.strikeRate, p.economy);
        string memory multStr = formatScaled(p.multiplierBps);
        string memory srStr = formatScaled(p.strikeRate);
        string memory econStr = formatScaled(p.economy);

        bytes memory part1 = abi.encodePacked(
            '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 340 480" width="100%" height="100%">',
            '<defs>',
            '<linearGradient id="cardGrad" x1="0" y1="0" x2="1" y2="1"><stop offset="0%" stop-color="#0F172A"/><stop offset="100%" stop-color="#1E293B"/></linearGradient>',
            '<filter id="glow" x="-20%" y="-20%" width="140%" height="140%"><feDropShadow dx="0" dy="6" stdDeviation="10" flood-color="', glow, '"/></filter>',
            '</defs>',
            '<rect x="10" y="10" width="320" height="460" rx="24" fill="url(#cardGrad)" stroke="', border, '" stroke-width="3" filter="url(#glow)"/>'
        );

        bytes memory part2 = _renderHeader(p.name, p.role, p.team, primary, border, multStr);

        bytes memory part3 = abi.encodePacked(
            '<rect x="24" y="96" width="292" height="150" rx="16" fill="#132238" stroke="#334155" stroke-width="1"/>',
            '<circle cx="170" cy="171" r="54" fill="#1E293B" stroke="', border, '" stroke-width="2"/>',
            '<text x="170" y="180" fill="', primary, '" font-size="34" font-family="Arial, sans-serif" text-anchor="middle">&#127951;</text>'
        );

        bytes memory part4 = _renderStats(p.matches, p.runs, p.wickets, srStr, econStr);

        return string(abi.encodePacked(part1, part2, part3, part4, badgeElements, '</svg>'));
    }

    /**
     * @notice Generates an RFC-2397 Data URI containing base64 encoded SVG
     */
    function generateCardTokenURI(CardVisualParams memory p) external pure returns (string memory) {
        string memory svg = renderCardSVG(p);
        string memory json = string(abi.encodePacked(
            '{"name":"', p.name, '",',
            '"description":"CricketVerse Dynamic Player Card with On-Chain Telemetry and Milestones",',
            '"attributes":[{"trait_type":"Role","value":"', p.role, '"},',
            '{"trait_type":"Team","value":"', p.team, '"},',
            '{"trait_type":"Runs","value":', uint256(p.runs).toString(), '},',
            '{"trait_type":"Wickets","value":', uint256(p.wickets).toString(), '}],',
            '"image":"data:image/svg+xml;base64,', Base64.encode(bytes(svg)), '"}'
        ));
        return string(abi.encodePacked("data:application/json;base64,", Base64.encode(bytes(json))));
    }
}

contracts/CRIC.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

import "@openzeppelin/contracts/token/ERC20/ERC20.sol";
import "@openzeppelin/contracts/token/ERC20/extensions/ERC20Burnable.sol";
import "@openzeppelin/contracts/access/Ownable.sol";

/**
 * @title CRIC Utility Token
 * @author Tejaswini Kunkulagunta (CS23B032)
 * @notice Native utility token for the CricketVerse Web3 Ecosystem.
 *         Used for fantasy entry, marketplace purchases, fan polls, and match ticketing.
 */
contract CRIC is ERC20, ERC20Burnable, Ownable {
    // Maximum supply cap: 100,000,000 CRIC
    uint256 public constant MAX_SUPPLY = 100_000_000 * 10 ** 18;

    // Faucet configuration for testing and prototype demonstrations
    uint256 public constant FAUCET_AMOUNT = 50_000 * 10 ** 18; // 50,000 CRIC per claim
    mapping(address => uint256) public lastFaucetClaim;
    uint256 public constant FAUCET_COOLDOWN = 1 hours;

    // Authorized minters (e.g., tournament reward escrow or marketplace contract)
    mapping(address => bool) public isAuthorizedMinter;

    event FaucetClaimed(address indexed recipient, uint256 amount);
    event MinterStatusUpdated(address indexed minter, bool status);

    constructor() ERC20("CricketVerse Token", "CRIC") Ownable(msg.sender) {
        // Initial genesis mint for platform liquidity, drops & tournament rewards (10M CRIC)
        _mint(msg.sender, 10_000_000 * 10 ** 18);
        isAuthorizedMinter[msg.sender] = true;
    }

    /**
     * @notice Set minter authorization status
     */
    function setMinter(address minter, bool status) external onlyOwner {
        isAuthorizedMinter[minter] = status;
        emit MinterStatusUpdated(minter, status);
    }

    /**
     * @notice Mint CRIC tokens (restricted to owner or authorized reward engines)
     */
    function mint(address to, uint256 amount) external {
        require(isAuthorizedMinter[msg.sender] || msg.sender == owner(), "CRIC: Caller not authorized to mint");
        require(totalSupply() + amount <= MAX_SUPPLY, "CRIC: Exceeds maximum supply cap");
        _mint(to, amount);
    }

    /**
     * @notice Interactive faucet allowing prototype users to request test tokens
     */
    function claimFaucet() external {
        require(
            block.timestamp >= lastFaucetClaim[msg.sender] + FAUCET_COOLDOWN,
            "CRIC: Faucet cooldown active. Please wait."
        );
        require(totalSupply() + FAUCET_AMOUNT <= MAX_SUPPLY, "CRIC: Maximum supply reached");

        lastFaucetClaim[msg.sender] = block.timestamp;
        _mint(msg.sender, FAUCET_AMOUNT);
        emit FaucetClaimed(msg.sender, FAUCET_AMOUNT);
    }
}

contracts/CricketMarketplace.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "@openzeppelin/contracts/token/ERC721/IERC721.sol";
import "@openzeppelin/contracts/token/ERC1155/IERC1155.sol";
import "@openzeppelin/contracts/token/ERC1155/utils/ERC1155Holder.sol";
import "@openzeppelin/contracts/token/ERC721/utils/ERC721Holder.sol";
import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import "@openzeppelin/contracts/access/Ownable.sol";
import "./MatchTicketNFT.sol";

/**
 * @title CricketMarketplace
 * @author Tejaswini Kunkulagunta (CS23B032)
 * @notice Trustless P2P marketplace for CricketVerse assets using CRIC tokens.
 *         Features atomic settlement, royalty fee routing, and anti-scalping price ceiling enforcement.
 */
contract CricketMarketplace is ReentrancyGuard, Ownable, ERC1155Holder, ERC721Holder {
    enum AssetType {
        PLAYER_CARD_1155,
        MATCH_TICKET_721
    }

    struct Listing {
        uint256 listingId;
        address seller;
        AssetType assetType;
        address assetContract;
        uint256 tokenId;
        uint256 amount; // 1 for ERC721, >= 1 for ERC1155
        uint256 pricePerUnit; // In CRIC (wei)
        bool isActive;
    }

    IERC20 public immutable cricToken;
    MatchTicketNFT public immutable ticketContract;
    address public royaltyReceiver;

    // Default royalty fee: 5% (500 bps / 10000)
    uint256 public royaltyBps = 500;
    uint256 public constant BPS_DENOMINATOR = 10000;

    uint256 public nextListingId = 1;
    mapping(uint256 => Listing) public listings;

    event ItemListed(
        uint256 indexed listingId,
        address indexed seller,
        AssetType assetType,
        address indexed assetContract,
        uint256 tokenId,
        uint256 amount,
        uint256 pricePerUnit
    );

    event ItemSold(
        uint256 indexed listingId,
        address indexed buyer,
        address indexed seller,
        uint256 amount,
        uint256 totalPrice,
        uint256 royaltyPaid
    );

    event ListingCancelled(uint256 indexed listingId, address indexed seller);
    event RoyaltyUpdated(address indexed receiver, uint256 royaltyBps);

    constructor(address _cricToken, address _ticketContract, address _royaltyReceiver) Ownable(msg.sender) {
        require(_cricToken != address(0), "Invalid CRIC address");
        require(_ticketContract != address(0), "Invalid Ticket address");
        require(_royaltyReceiver != address(0), "Invalid Royalty receiver");

        cricToken = IERC20(_cricToken);
        ticketContract = MatchTicketNFT(_ticketContract);
        royaltyReceiver = _royaltyReceiver;
    }

    function setRoyalty(address _royaltyReceiver, uint256 _royaltyBps) external onlyOwner {
        require(_royaltyBps <= 2000, "Royalty cannot exceed 20%");
        require(_royaltyReceiver != address(0), "Invalid address");
        royaltyReceiver = _royaltyReceiver;
        royaltyBps = _royaltyBps;
        emit RoyaltyUpdated(_royaltyReceiver, _royaltyBps);
    }

    /**
     * @notice List an ERC-1155 Dynamic Player Card for sale
     */
    function listPlayerCard(
        address assetContract,
        uint256 tokenId,
        uint256 amount,
        uint256 pricePerUnit
    ) external nonReentrant returns (uint256) {
        require(amount > 0, "Amount must be > 0");
        require(pricePerUnit > 0, "Price must be > 0");

        // Transfer card into marketplace escrow
        IERC1155(assetContract).safeTransferFrom(msg.sender, address(this), tokenId, amount, "");

        uint256 listingId = nextListingId++;
        listings[listingId] = Listing({
            listingId: listingId,
            seller: msg.sender,
            assetType: AssetType.PLAYER_CARD_1155,
            assetContract: assetContract,
            tokenId: tokenId,
            amount: amount,
            pricePerUnit: pricePerUnit,
            isActive: true
        });

        emit ItemListed(listingId, msg.sender, AssetType.PLAYER_CARD_1155, assetContract, tokenId, amount, pricePerUnit);
        return listingId;
    }

    /**
     * @notice List an ERC-721 Stadium Match Ticket with strict anti-scalping price ceiling enforcement
     */
    function listMatchTicket(
        address assetContract,
        uint256 tokenId,
        uint256 price
    ) external nonReentrant returns (uint256) {
        require(price > 0, "Price must be > 0");

        // ANTI-SCALPING CHECK: Verify proposed price does NOT exceed 15% markup ceiling
        if (assetContract == address(ticketContract)) {
            require(
                ticketContract.isPriceWithinAntiScalpingCap(tokenId, price),
                "Marketplace: Scalping detected! Resale price exceeds 15% ceiling"
            );
            MatchTicketNFT.TicketDetails memory details = ticketContract.getTicket(tokenId);
            require(!details.isRedeemed, "Marketplace: Cannot list already redeemed ticket");
            (, uint64 endsAt) = ticketContract.matchWindows(tokenId);
            require(block.timestamp < endsAt, "Marketplace: Ticket match has ended");
        }

        // Transfer ticket into marketplace escrow
        IERC721(assetContract).safeTransferFrom(msg.sender, address(this), tokenId);

        uint256 listingId = nextListingId++;
        listings[listingId] = Listing({
            listingId: listingId,
            seller: msg.sender,
            assetType: AssetType.MATCH_TICKET_721,
            assetContract: assetContract,
            tokenId: tokenId,
            amount: 1,
            pricePerUnit: price,
            isActive: true
        });

        emit ItemListed(listingId, msg.sender, AssetType.MATCH_TICKET_721, assetContract, tokenId, 1, price);
        return listingId;
    }

    /**
     * @notice Execute atomic purchase using CRIC tokens with automatic royalty split
     */
    function buyItem(uint256 listingId, uint256 buyAmount) external nonReentrant {
        Listing storage listing = listings[listingId];
        require(listing.isActive, "Listing is not active");
        require(buyAmount > 0 && buyAmount <= listing.amount, "Invalid purchase amount");
        require(msg.sender != listing.seller, "Seller cannot purchase own listing");

        // A gatekeeper can redeem a ticket while it is escrowed. Never deliver a
        // redeemed ticket to a buyer even if the listing was valid when created.
        if (listing.assetType == AssetType.MATCH_TICKET_721 && listing.assetContract == address(ticketContract)) {
            MatchTicketNFT.TicketDetails memory details = ticketContract.getTicket(listing.tokenId);
            require(!details.isRedeemed, "Marketplace: Cannot sell redeemed ticket");
            (, uint64 endsAt) = ticketContract.matchWindows(listing.tokenId);
            require(block.timestamp < endsAt, "Marketplace: Ticket match has ended");
        }

        uint256 totalCost = listing.pricePerUnit * buyAmount;
        uint256 royaltyAmount = (totalCost * royaltyBps) / BPS_DENOMINATOR;
        uint256 sellerProceeds = totalCost - royaltyAmount;

        listing.amount -= buyAmount;
        if (listing.amount == 0) {
            listing.isActive = false;
        }

        // 1. Transfer CRIC payment: proceeds to seller
        require(cricToken.transferFrom(msg.sender, listing.seller, sellerProceeds), "CRIC payment to seller failed");

        // 2. Transfer CRIC royalty: platform / drop pool share
        if (royaltyAmount > 0) {
            require(cricToken.transferFrom(msg.sender, royaltyReceiver, royaltyAmount), "CRIC royalty payment failed");
        }

        // 3. Transfer Asset to Buyer
        if (listing.assetType == AssetType.PLAYER_CARD_1155) {
            IERC1155(listing.assetContract).safeTransferFrom(address(this), msg.sender, listing.tokenId, buyAmount, "");
        } else {
            IERC721(listing.assetContract).safeTransferFrom(address(this), msg.sender, listing.tokenId);
        }

        emit ItemSold(listingId, msg.sender, listing.seller, buyAmount, totalCost, royaltyAmount);
    }

    /**
     * @notice Cancel listing and return escrowed assets
     */
    function cancelListing(uint256 listingId) external nonReentrant {
        Listing storage listing = listings[listingId];
        require(listing.isActive, "Listing not active");
        require(listing.seller == msg.sender || msg.sender == owner(), "Not seller or owner");

        listing.isActive = false;

        if (listing.assetType == AssetType.PLAYER_CARD_1155) {
            IERC1155(listing.assetContract).safeTransferFrom(address(this), listing.seller, listing.tokenId, listing.amount, "");
        } else {
            IERC721(listing.assetContract).safeTransferFrom(address(this), listing.seller, listing.tokenId);
        }

        emit ListingCancelled(listingId, listing.seller);
    }

    /**
     * @notice View listing details
     */
    function getListing(uint256 listingId) external view returns (Listing memory) {
        return listings[listingId];
    }
}

contracts/CricketOracleConsumer.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

import "@openzeppelin/contracts/access/Ownable.sol";
import "./PlayerCardNFT.sol";

/**
 * @title CricketOracleConsumer
 * @author Tejaswini Kunkulagunta (CS23B032)
 * @notice Oracle consumer and bridge contract adhering to Chainlink Functions architecture.
 *         Receives off-chain sports API telemetry (CricAPI/Sportradar) and cryptographically
 *         commits verified match outcomes to PlayerCardNFT on-chain.
 */
contract CricketOracleConsumer is Ownable {
    // Reference to dynamic NFT contract
    PlayerCardNFT public immutable playerCardContract;

    // Authorized oracle relayers / Chainlink Functions router addresses
    mapping(address => bool) public isAuthorizedOracle;

    struct OracleRequest {
        uint256 matchId;
        uint256 cardId;
        string apiEndpoint;
        uint256 timestamp;
        bool isFulfilled;
    }

    // Request nonce tracking
    uint256 private _requestNonce;
    mapping(bytes32 => OracleRequest) public requests;

    event StatsRequested(bytes32 indexed requestId, uint256 indexed matchId, uint256 indexed cardId, string endpoint);
    event StatsFulfilled(
        bytes32 indexed requestId,
        uint256 indexed cardId,
        uint32 additionalRuns,
        uint32 additionalWickets,
        uint32 strikeRate,
        uint32 economy
    );
    event OracleAuthorizationUpdated(address indexed oracle, bool status);

    modifier onlyOracleOrOwner() {
        require(isAuthorizedOracle[msg.sender] || msg.sender == owner(), "CricketOracleConsumer: Unauthorized oracle caller");
        _;
    }

    constructor(address _playerCardAddress) Ownable(msg.sender) {
        require(_playerCardAddress != address(0), "CricketOracleConsumer: Invalid card address");
        playerCardContract = PlayerCardNFT(_playerCardAddress);
        isAuthorizedOracle[msg.sender] = true;
    }

    /**
     * @notice Set or revoke oracle router / relayer authorization
     */
    function setOracleAuthorization(address oracle, bool status) external onlyOwner {
        require(oracle != address(0), "CricketOracleConsumer: Invalid address");
        isAuthorizedOracle[oracle] = status;
        emit OracleAuthorizationUpdated(oracle, status);
    }

    /**
     * @notice Dispatch oracle query request to fetch player match telemetry
     */
    function requestMatchStats(
        uint256 matchId,
        uint256 cardId,
        string memory apiEndpoint
    ) external onlyOracleOrOwner returns (bytes32 requestId) {
        _requestNonce++;
        requestId = keccak256(abi.encodePacked(block.timestamp, msg.sender, matchId, cardId, _requestNonce));

        requests[requestId] = OracleRequest({
            matchId: matchId,
            cardId: cardId,
            apiEndpoint: apiEndpoint,
            timestamp: block.timestamp,
            isFulfilled: false
        });

        emit StatsRequested(requestId, matchId, cardId, apiEndpoint);
        return requestId;
    }

    /**
     * @notice Fulfill oracle telemetry request and update player card on-chain
     */
    function fulfillRequest(
        bytes32 requestId,
        uint32 additionalRuns,
        uint32 additionalWickets,
        uint32 newStrikeRate,
        uint32 newEconomy
    ) external onlyOracleOrOwner {
        OracleRequest storage req = requests[requestId];
        require(req.timestamp != 0, "CricketOracleConsumer: Request not found");
        require(!req.isFulfilled, "CricketOracleConsumer: Request already fulfilled");

        req.isFulfilled = true;

        // Propagate dynamic mutation to PlayerCardNFT
        playerCardContract.updatePlayerStats(
            req.cardId,
            additionalRuns,
            additionalWickets,
            newStrikeRate,
            newEconomy
        );

        emit StatsFulfilled(
            requestId,
            req.cardId,
            additionalRuns,
            additionalWickets,
            newStrikeRate,
            newEconomy
        );
    }

    /**
     * @notice Direct emergency batch sync for post-match finalization
     */
    function batchSyncMatchStats(
        uint256[] calldata cardIds,
        uint32[] calldata additionalRuns,
        uint32[] calldata additionalWickets,
        uint32[] calldata newStrikeRates,
        uint32[] calldata newEconomies
    ) external onlyOracleOrOwner {
        require(
            cardIds.length == additionalRuns.length &&
            cardIds.length == additionalWickets.length &&
            cardIds.length == newStrikeRates.length &&
            cardIds.length == newEconomies.length,
            "CricketOracleConsumer: Array length mismatch"
        );

        for (uint256 i = 0; i < cardIds.length; i++) {
            playerCardContract.updatePlayerStats(
                cardIds[i],
                additionalRuns[i],
                additionalWickets[i],
                newStrikeRates[i],
                newEconomies[i]
            );
        }
    }
}

contracts/FanPolls.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";

/// @notice On-chain fan polls. Every vote is a wallet transaction and is counted once per address.
contract FanPolls is Ownable {
    using SafeERC20 for IERC20;

    uint256 public constant VOTE_REWARD = 10 ether;
    IERC20 public immutable cricToken;
    struct Poll {
        string question;
        uint64 closesAt;
        uint256 totalVotes;
        bool exists;
    }

    uint256 public pollCount;
    mapping(uint256 => Poll) private _polls;
    mapping(uint256 => string[]) private _options;
    mapping(uint256 => mapping(uint256 => uint256)) private _votes;
    mapping(uint256 => mapping(address => bool)) public hasVoted;

    event PollCreated(uint256 indexed pollId, string question, uint64 closesAt);
    event VoteCast(uint256 indexed pollId, address indexed voter, uint256 indexed optionIndex, uint256 reward);

    constructor(address cricTokenAddress) Ownable(msg.sender) {
        require(cricTokenAddress != address(0), "Poll: token required");
        cricToken = IERC20(cricTokenAddress);
    }

    function createPoll(string calldata question, string[] calldata options, uint64 closesAt)
        external onlyOwner returns (uint256 pollId)
    {
        require(bytes(question).length > 0, "Poll: question required");
        require(options.length >= 2 && options.length <= 8, "Poll: use 2-8 options");
        require(closesAt > block.timestamp, "Poll: close time must be future");
        pollId = ++pollCount;
        Poll storage poll = _polls[pollId];
        poll.question = question;
        poll.closesAt = closesAt;
        poll.exists = true;
        for (uint256 i; i < options.length; ++i) {
            require(bytes(options[i]).length > 0, "Poll: empty option");
            _options[pollId].push(options[i]);
        }
        emit PollCreated(pollId, question, closesAt);
    }

    function vote(uint256 pollId, uint256 optionIndex) external {
        Poll storage poll = _polls[pollId];
        require(poll.exists, "Poll: not found");
        require(block.timestamp < poll.closesAt, "Poll: closed");
        require(optionIndex < _options[pollId].length, "Poll: invalid option");
        require(!hasVoted[pollId][msg.sender], "Poll: already voted");
        hasVoted[pollId][msg.sender] = true;
        _votes[pollId][optionIndex]++;
        poll.totalVotes++;
        cricToken.safeTransfer(msg.sender, VOTE_REWARD);
        emit VoteCast(pollId, msg.sender, optionIndex, VOTE_REWARD);
    }

    function getPoll(uint256 pollId) external view returns (
        string memory question,
        string[] memory options,
        uint256[] memory voteCounts,
        uint256 totalVotes,
        uint64 closesAt,
        bool active
    ) {
        Poll storage poll = _polls[pollId];
        require(poll.exists, "Poll: not found");
        uint256 length = _options[pollId].length;
        options = new string[](length);
        voteCounts = new uint256[](length);
        for (uint256 i; i < length; ++i) {
            options[i] = _options[pollId][i];
            voteCounts[i] = _votes[pollId][i];
        }
        return (poll.question, options, voteCounts, poll.totalVotes, poll.closesAt, block.timestamp < poll.closesAt);
    }
}

contracts/MatchTicketNFT.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

import "@openzeppelin/contracts/token/ERC721/ERC721.sol";
import "@openzeppelin/contracts/access/AccessControl.sol";

/**
 * @title MatchTicketNFT (Anti-Scalping Dynamic Ticket)
 * @author Tejaswini Kunkulagunta (CS23B032)
 * @notice ERC-721 NFT for stadium match admissions featuring:
 *         1. Enforced secondary resale markup ceiling (max 15% above face value)
 *         2. Permanent one-time gatekeeper redemption (anti-double entry)
 *         3. Cryptographic gate verification support
 */
contract MatchTicketNFT is ERC721, AccessControl {
    bytes32 public constant GATEKEEPER_ROLE = keccak256("GATEKEEPER_ROLE");
    bytes32 public constant ORGANIZER_ROLE = keccak256("ORGANIZER_ROLE");

    // Resale price markup cap: 15% (115% of face value in basis points: 11500 / 10000)
    uint256 public constant MAX_MARKUP_BPS = 11500;
    uint256 public constant BPS_DENOMINATOR = 10000;

    struct TicketDetails {
        uint256 matchId;
        string matchName;
        string venue;
        string stand;
        string seatNumber;
        uint256 faceValue;      // In CRIC tokens (or wei)
        uint256 maxResalePrice; // Calculated as faceValue * 115 / 100
        bool isRedeemed;
        uint256 redeemedAt;
        address redeemedByGatekeeper;
        bool exists;
    }

    mapping(uint256 => TicketDetails) public tickets;
    struct MatchWindow { uint64 startsAt; uint64 endsAt; }
    mapping(uint256 => MatchWindow) public matchWindows;

    event TicketIssued(uint256 indexed tokenId, address indexed initialHolder, uint256 faceValue, uint256 maxResalePrice);
    event MatchWindowSet(uint256 indexed tokenId, uint64 startsAt, uint64 endsAt);
    event TicketRedeemed(uint256 indexed tokenId, address indexed attendee, address indexed gatekeeper, uint256 timestamp);

    constructor() ERC721("CricketVerse Match Ticket", "CVTKT") {
        _grantRole(DEFAULT_ADMIN_ROLE, msg.sender);
        _grantRole(ORGANIZER_ROLE, msg.sender);
        _grantRole(GATEKEEPER_ROLE, msg.sender);
    }

    /**
     * @notice Mint and issue a stadium ticket
     */
    function issueTicket(
        address recipient,
        uint256 tokenId,
        uint256 matchId,
        string memory matchName,
        string memory venue,
        string memory stand,
        string memory seatNumber,
        uint256 faceValue
    ) external onlyRole(ORGANIZER_ROLE) {
        _issueTicket(recipient, tokenId, matchId, matchName, venue, stand, seatNumber, faceValue);
        uint64 startsAt = uint64(block.timestamp);
        uint64 endsAt = uint64(block.timestamp + 4 hours);
        matchWindows[tokenId] = MatchWindow(startsAt, endsAt);
        emit MatchWindowSet(tokenId, startsAt, endsAt);
    }

    /// @notice Issue a ticket with an on-chain fixture window for live/upcoming/past status.
    function issueScheduledTicket(
        address recipient,
        uint256 tokenId,
        uint256 matchId,
        string memory matchName,
        string memory venue,
        string memory stand,
        string memory seatNumber,
        uint256 faceValue,
        uint64 startsAt,
        uint64 endsAt
    ) external onlyRole(ORGANIZER_ROLE) {
        require(startsAt > 0 && endsAt > startsAt, "Match window: invalid times");
        _issueTicket(recipient, tokenId, matchId, matchName, venue, stand, seatNumber, faceValue);
        matchWindows[tokenId] = MatchWindow(startsAt, endsAt);
        emit MatchWindowSet(tokenId, startsAt, endsAt);
    }

    function _issueTicket(
        address recipient,
        uint256 tokenId,
        uint256 matchId,
        string memory matchName,
        string memory venue,
        string memory stand,
        string memory seatNumber,
        uint256 faceValue
    ) internal {
        require(!tickets[tokenId].exists, "MatchTicketNFT: Token ID already issued");
        require(faceValue > 0, "MatchTicketNFT: Face value must be greater than zero");

        uint256 maxResalePrice = (faceValue * MAX_MARKUP_BPS) / BPS_DENOMINATOR;

        tickets[tokenId] = TicketDetails({
            matchId: matchId,
            matchName: matchName,
            venue: venue,
            stand: stand,
            seatNumber: seatNumber,
            faceValue: faceValue,
            maxResalePrice: maxResalePrice,
            isRedeemed: false,
            redeemedAt: 0,
            redeemedByGatekeeper: address(0),
            exists: true
        });

        _mint(recipient, tokenId);
        emit TicketIssued(tokenId, recipient, faceValue, maxResalePrice);
    }

    /**
     * @notice Check whether a resale price conforms to anti-scalping ceiling
     */
    function isPriceWithinAntiScalpingCap(uint256 tokenId, uint256 proposedPrice) public view returns (bool) {
        require(tickets[tokenId].exists, "MatchTicketNFT: Ticket does not exist");
        return proposedPrice <= tickets[tokenId].maxResalePrice;
    }

    /**
     * @notice One-time gate redemption by authorized gatekeeper
     */
    function redeemTicket(uint256 tokenId) external onlyRole(GATEKEEPER_ROLE) {
        require(tickets[tokenId].exists, "MatchTicketNFT: Ticket does not exist");
        require(!tickets[tokenId].isRedeemed, "MatchTicketNFT: Ticket already redeemed (Double-Entry Blocked)");
        MatchWindow memory window = matchWindows[tokenId];
        require(block.timestamp >= window.startsAt && block.timestamp < window.endsAt, "Match window: not active");

        address currentHolder = ownerOf(tokenId);
        tickets[tokenId].isRedeemed = true;
        tickets[tokenId].redeemedAt = block.timestamp;
        tickets[tokenId].redeemedByGatekeeper = msg.sender;

        emit TicketRedeemed(tokenId, currentHolder, msg.sender, block.timestamp);
    }

    /**
     * @notice Get ticket details
     */
    function getTicket(uint256 tokenId) external view returns (TicketDetails memory) {
        require(tickets[tokenId].exists, "MatchTicketNFT: Ticket does not exist");
        return tickets[tokenId];
    }

    // Explicit override for ERC-721 and AccessControl
    function supportsInterface(bytes4 interfaceId)
        public
        view
        virtual
        override(ERC721, AccessControl)
        returns (bool)
    {
        return super.supportsInterface(interfaceId);
    }
}

contracts/PlayerCardNFT.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

import "@openzeppelin/contracts/token/ERC1155/ERC1155.sol";
import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/utils/Strings.sol";
import "@openzeppelin/contracts/token/ERC20/IERC20.sol";

/**
 * @title PlayerCardNFT (Dynamic NFT - dNFT)
 * @author Tejaswini Kunkulagunta (CS23B032)
 * @notice ERC-1155 multi-token standard representing dynamic cricket player cards.
 *         Includes tiered multipliers, supply caps, and dynamic telemetry upgrades.
 */
contract PlayerCardNFT is ERC1155, Ownable {
    using Strings for uint256;

    enum RarityTier {
        Common,      // 0: 1.00x multiplier, Unlimited
        Uncommon,    // 1: 1.10x multiplier, Cap: 5,000
        Rare,        // 2: 1.25x multiplier, Cap: 1,000
        Epic,        // 3: 1.50x multiplier, Cap: 250
        Legendary    // 4: 2.00x multiplier, Cap: 25
    }

    struct CardMetadata {
        string name;
        string role;           // "Batsman", "Bowler", "All-Rounder", "Wicketkeeper"
        string team;
        RarityTier rarity;
        uint16 multiplierBps;  // 100 = 1.0x, 110 = 1.1x, 125 = 1.25x, 150 = 1.5x, 200 = 2.0x
        uint32 matches;
        uint32 runs;
        uint32 wickets;
        uint32 strikeRate;     // Scaled by 100 (e.g. 14550 = 145.50)
        uint32 economy;        // Scaled by 100 (e.g. 720 = 7.20)
        string imageURI;
        bool exists;
    }

    struct CardRegistration {
        uint256 cardId;
        string name;
        string role;
        string team;
        RarityTier rarity;
        uint32 matches;
        uint32 runs;
        uint32 wickets;
        uint32 strikeRate;
        uint32 economy;
        string imageURI;
    }

    // Supply Caps per Rarity Tier
    uint256 public constant UNCOMMON_CAP = 5000;
    uint256 public constant RARE_CAP = 1000;
    uint256 public constant EPIC_CAP = 250;
    uint256 public constant LEGENDARY_CAP = 25;

    // Card ID => Metadata
    mapping(uint256 => CardMetadata) public cards;
    // Card ID => Total Minted Supply
    mapping(uint256 => uint256) public totalMinted;

    // Authorized Oracles / Updaters (for dynamic stats telemetry)
    mapping(address => bool) public isAuthorizedUpdater;
    IERC20 public paymentToken;
    uint256 public primaryMintPrice;

    event CardRegistered(uint256 indexed cardId, string name, RarityTier rarity, uint16 multiplierBps);
    event CardMinted(address indexed recipient, uint256 indexed cardId, uint256 amount);
    event StatsUpdated(uint256 indexed cardId, uint32 runs, uint32 wickets, uint32 strikeRate, uint32 economy);
    event UpdaterSet(address indexed updater, bool status);
    event PrimarySaleConfigured(address indexed paymentToken, uint256 price);
    event PrimaryCardPurchased(address indexed buyer, uint256 indexed cardId, uint256 price);

    constructor() ERC1155("https://api.cricketverse.io/metadata/{id}.json") Ownable(msg.sender) {
        isAuthorizedUpdater[msg.sender] = true;
    }

    modifier onlyUpdaterOrOwner() {
        require(isAuthorizedUpdater[msg.sender] || msg.sender == owner(), "PlayerCardNFT: Caller not authorized");
        _;
    }

    function setUpdater(address updater, bool status) external onlyOwner {
        isAuthorizedUpdater[updater] = status;
        emit UpdaterSet(updater, status);
    }

    function configurePrimarySale(address token, uint256 price) external onlyOwner {
        require(token != address(0), "PlayerCardNFT: Invalid payment token");
        require(price > 0, "PlayerCardNFT: Price must be positive");
        paymentToken = IERC20(token);
        primaryMintPrice = price;
        emit PrimarySaleConfigured(token, price);
    }

    function buyCard(uint256 cardId) external {
        require(address(paymentToken) != address(0), "PlayerCardNFT: Primary sale not configured");
        require(cards[cardId].exists, "PlayerCardNFT: Card not registered");
        require(paymentToken.transferFrom(msg.sender, owner(), primaryMintPrice), "PlayerCardNFT: Payment failed");
        _mintCard(msg.sender, cardId, 1);
        emit PrimaryCardPurchased(msg.sender, cardId, primaryMintPrice);
    }

    /**
     * @notice Register a player card specification with predefined rarity and supply constraints
     */
    function registerCard(
        uint256 cardId,
        string memory name,
        string memory role,
        string memory team,
        RarityTier rarity,
        uint32 matches,
        uint32 runs,
        uint32 wickets,
        uint32 strikeRate,
        uint32 economy,
        string memory imageURI
    ) external onlyOwner {
        _registerCard(CardRegistration(cardId, name, role, team, rarity, matches, runs, wickets, strikeRate, economy, imageURI));
    }

    function registerCards(CardRegistration[] calldata registrations) external onlyOwner {
        require(registrations.length > 0 && registrations.length <= 50, "PlayerCardNFT: Batch size must be 1-50");
        for (uint256 i = 0; i < registrations.length; i++) _registerCard(registrations[i]);
    }

    function _registerCard(CardRegistration memory registration) private {
        uint256 cardId = registration.cardId;
        require(!cards[cardId].exists, "PlayerCardNFT: Card ID already registered");

        uint16 multiplierBps;
        if (registration.rarity == RarityTier.Common) multiplierBps = 100;
        else if (registration.rarity == RarityTier.Uncommon) multiplierBps = 110;
        else if (registration.rarity == RarityTier.Rare) multiplierBps = 125;
        else if (registration.rarity == RarityTier.Epic) multiplierBps = 150;
        else if (registration.rarity == RarityTier.Legendary) multiplierBps = 200;

        cards[cardId] = CardMetadata({
            name: registration.name,
            role: registration.role,
            team: registration.team,
            rarity: registration.rarity,
            multiplierBps: multiplierBps,
            matches: registration.matches,
            runs: registration.runs,
            wickets: registration.wickets,
            strikeRate: registration.strikeRate,
            economy: registration.economy,
            imageURI: registration.imageURI,
            exists: true
        });

        emit CardRegistered(cardId, registration.name, registration.rarity, multiplierBps);
    }

    /**
     * @notice Mint card editions enforcing rarity supply cap constraints
     */
    function mintCard(address to, uint256 cardId, uint256 amount) external onlyUpdaterOrOwner {
        _mintCard(to, cardId, amount);
    }

    function _mintCard(address to, uint256 cardId, uint256 amount) internal {
        require(amount > 0, "PlayerCardNFT: Amount must be greater than zero");
        require(cards[cardId].exists, "PlayerCardNFT: Card not registered");
        CardMetadata memory meta = cards[cardId];

        uint256 newTotal = totalMinted[cardId] + amount;
        if (meta.rarity == RarityTier.Uncommon) {
            require(newTotal <= UNCOMMON_CAP, "PlayerCardNFT: Exceeds Uncommon supply cap");
        } else if (meta.rarity == RarityTier.Rare) {
            require(newTotal <= RARE_CAP, "PlayerCardNFT: Exceeds Rare supply cap");
        } else if (meta.rarity == RarityTier.Epic) {
            require(newTotal <= EPIC_CAP, "PlayerCardNFT: Exceeds Epic supply cap");
        } else if (meta.rarity == RarityTier.Legendary) {
            require(newTotal <= LEGENDARY_CAP, "PlayerCardNFT: Exceeds Legendary supply cap");
        }

        totalMinted[cardId] = newTotal;
        _mint(to, cardId, amount, "");
        emit CardMinted(to, cardId, amount);
    }

    /**
     * @notice Dynamic metadata telemetry update - called by oracle/oracle-indexer
     */
    function updatePlayerStats(
        uint256 cardId,
        uint32 additionalRuns,
        uint32 additionalWickets,
        uint32 newStrikeRate,
        uint32 newEconomy
    ) external onlyUpdaterOrOwner {
        require(cards[cardId].exists, "PlayerCardNFT: Card does not exist");
        CardMetadata storage card = cards[cardId];

        card.matches += 1;
        card.runs += additionalRuns;
        card.wickets += additionalWickets;
        card.strikeRate = newStrikeRate;
        card.economy = newEconomy;

        emit StatsUpdated(cardId, card.runs, card.wickets, newStrikeRate, newEconomy);
    }

    /**
     * @notice Retrieve card metadata
     */
    function getCard(uint256 cardId) external view returns (CardMetadata memory) {
        require(cards[cardId].exists, "PlayerCardNFT: Card does not exist");
        return cards[cardId];
    }
}

contracts/TournamentPool.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";

/**
 * @title TournamentPool
 * @author Tejaswini Kunkulagunta (CS23B032)
 * @notice Trustless, non-custodial fantasy tournament escrow contract.
 *         Locks entry fees in CRIC utility tokens, enforces match lock windows,
 *         and programmatically disburses prize pools to verified leaderboard winners.
 */
contract TournamentPool is Ownable, ReentrancyGuard {
    IERC20 public immutable cricToken;

    // Platform treasury address for organizer fee (5% = 500 bps)
    address public treasury;
    uint256 public constant PLATFORM_FEE_BPS = 500;
    uint256 public constant BPS_DENOMINATOR = 10000;

    enum TournamentStatus {
        Open,        // Accepting participant registrations
        Locked,      // Match live, registrations closed
        Settled,     // Winners paid out programmatically
        Cancelled    // Match abandoned; full refund available
    }

    struct Participant {
        address user;
        bytes32 squadHash;
        uint256 joinedAt;
        bool refunded;
    }

    struct Tournament {
        uint256 id;
        string name;
        uint256 matchId;
        uint256 entryFee;          // In CRIC tokens (wei)
        uint256 maxParticipants;
        uint256 lockTimestamp;     // Match commencement time
        uint256 totalEscrow;       // Total CRIC locked
        TournamentStatus status;
        uint256 totalWinners;
        bool exists;
    }

    uint256 public tournamentCount;
    mapping(uint256 => Tournament) public tournaments;
    mapping(uint256 => Participant[]) internal _participants;
    mapping(uint256 => mapping(address => bool)) public hasJoined;

    event TournamentCreated(
        uint256 indexed tournamentId,
        string name,
        uint256 indexed matchId,
        uint256 entryFee,
        uint256 maxParticipants,
        uint256 lockTimestamp
    );
    event JoinedTournament(uint256 indexed tournamentId, address indexed participant, bytes32 squadHash, uint256 feePaid);
    event TournamentLocked(uint256 indexed tournamentId);
    event PrizesDistributed(uint256 indexed tournamentId, uint256 totalPayout, uint256 platformFee);
    event PrizePaid(uint256 indexed tournamentId, address indexed winner, uint256 amount);
    event TournamentCancelled(uint256 indexed tournamentId, string reason);
    event EntryFeeRefunded(uint256 indexed tournamentId, address indexed participant, uint256 refundAmount);
    event TreasuryUpdated(address indexed newTreasury);

    constructor(address _cricTokenAddress, address _treasury) Ownable(msg.sender) {
        require(_cricTokenAddress != address(0), "TournamentPool: Invalid token address");
        require(_treasury != address(0), "TournamentPool: Invalid treasury address");
        cricToken = IERC20(_cricTokenAddress);
        treasury = _treasury;
    }

    function setTreasury(address newTreasury) external onlyOwner {
        require(newTreasury != address(0), "TournamentPool: Invalid treasury");
        treasury = newTreasury;
        emit TreasuryUpdated(newTreasury);
    }

    /**
     * @notice Create a new fantasy contest escrow pool
     */
    function createTournament(
        string memory name,
        uint256 matchId,
        uint256 entryFee,
        uint256 maxParticipants,
        uint256 lockTimestamp
    ) external onlyOwner returns (uint256) {
        require(bytes(name).length > 0, "TournamentPool: Name cannot be empty");
        require(maxParticipants >= 2, "TournamentPool: Minimum 2 participants required");
        require(entryFee > 0, "TournamentPool: Entry fee must be greater than zero");
        require(lockTimestamp > block.timestamp, "TournamentPool: Lock time must be in future");

        tournamentCount++;
        uint256 tId = tournamentCount;

        tournaments[tId] = Tournament({
            id: tId,
            name: name,
            matchId: matchId,
            entryFee: entryFee,
            maxParticipants: maxParticipants,
            lockTimestamp: lockTimestamp,
            totalEscrow: 0,
            status: TournamentStatus.Open,
            totalWinners: 0,
            exists: true
        });

        emit TournamentCreated(tId, name, matchId, entryFee, maxParticipants, lockTimestamp);
        return tId;
    }

    /**
     * @notice Join an open tournament by locking the CRIC entry fee into escrow
     */
    function joinTournament(uint256 tournamentId, bytes32 squadHash) external nonReentrant {
        Tournament storage t = tournaments[tournamentId];
        require(t.exists, "TournamentPool: Tournament does not exist");
        require(t.status == TournamentStatus.Open, "TournamentPool: Tournament is not open");
        require(block.timestamp < t.lockTimestamp, "TournamentPool: Tournament registration closed");
        require(_participants[tournamentId].length < t.maxParticipants, "TournamentPool: Contest is full");
        require(!hasJoined[tournamentId][msg.sender], "TournamentPool: User already joined");
        require(squadHash != bytes32(0), "TournamentPool: Squad commitment required");

        hasJoined[tournamentId][msg.sender] = true;
        t.totalEscrow += t.entryFee;

        _participants[tournamentId].push(Participant({
            user: msg.sender,
            squadHash: squadHash,
            joinedAt: block.timestamp,
            refunded: false
        }));

        if (t.entryFee > 0) {
            bool success = cricToken.transferFrom(msg.sender, address(this), t.entryFee);
            require(success, "TournamentPool: CRIC transfer failed");
        }

        emit JoinedTournament(tournamentId, msg.sender, squadHash, t.entryFee);
    }

    /**
     * @notice Lock tournament registrations once match starts
     */
    function lockTournament(uint256 tournamentId) external onlyOwner {
        Tournament storage t = tournaments[tournamentId];
        require(t.exists, "TournamentPool: Tournament does not exist");
        require(t.status == TournamentStatus.Open, "TournamentPool: Not open");

        t.status = TournamentStatus.Locked;
        emit TournamentLocked(tournamentId);
    }

    /**
     * @notice Programmatic, trustless payout to verified leaderboard winners
     * @param tournamentId ID of contest
     * @param winners Ordered list of winning addresses
     * @param sharesBps Proportional payout share in basis points (must sum to 10000 = 100% of net pool)
     */
    function distributePrizes(
        uint256 tournamentId,
        address[] calldata winners,
        uint256[] calldata sharesBps
    ) external onlyOwner nonReentrant {
        Tournament storage t = tournaments[tournamentId];
        require(t.exists, "TournamentPool: Tournament does not exist");
        require(t.status == TournamentStatus.Locked, "TournamentPool: Tournament must be locked before settlement");
        require(winners.length > 0 && winners.length == sharesBps.length, "TournamentPool: Invalid winners or shares");
        require(winners.length <= _participants[tournamentId].length, "TournamentPool: Too many winners");

        // Only registered participants can receive prize funds; reject duplicate addresses
        // so a caller cannot allocate several shares to the same winner.
        for (uint256 i = 0; i < winners.length; i++) {
            require(winners[i] != address(0), "TournamentPool: Invalid winner");
            require(hasJoined[tournamentId][winners[i]], "TournamentPool: Winner did not join");
            for (uint256 j = 0; j < i; j++) {
                require(winners[i] != winners[j], "TournamentPool: Duplicate winner");
            }
        }

        uint256 totalEscrow = t.totalEscrow;
        require(totalEscrow > 0, "TournamentPool: No escrow funds");

        t.status = TournamentStatus.Settled;
        t.totalWinners = winners.length;

        // Calculate platform organizer fee (5%)
        uint256 platformFee = (totalEscrow * PLATFORM_FEE_BPS) / BPS_DENOMINATOR;
        uint256 netPrizePool = totalEscrow - platformFee;

        // Transfer platform fee to ecosystem treasury
        if (platformFee > 0) {
            bool feeSuccess = cricToken.transfer(treasury, platformFee);
            require(feeSuccess, "TournamentPool: Treasury fee transfer failed");
        }

        // Validate that shares sum to 10000 bps (100%)
        uint256 totalShares = 0;
        for (uint256 i = 0; i < sharesBps.length; i++) {
            totalShares += sharesBps[i];
        }
        require(totalShares == BPS_DENOMINATOR, "TournamentPool: Shares must sum to 10000 bps");

        // Disburse prizes to winners
        uint256 remainingPrizePool = netPrizePool;
        for (uint256 i = 0; i < winners.length; i++) {
            uint256 payout = i == winners.length - 1
                ? remainingPrizePool
                : (netPrizePool * sharesBps[i]) / BPS_DENOMINATOR;
            remainingPrizePool -= payout;
            if (payout > 0) {
                bool paySuccess = cricToken.transfer(winners[i], payout);
                require(paySuccess, "TournamentPool: Winner payout failed");
            }
            emit PrizePaid(tournamentId, winners[i], payout);
        }

        emit PrizesDistributed(tournamentId, netPrizePool, platformFee);
    }

    /**
     * @notice Cancel contest if match is washed out or abandoned
     */
    function cancelTournament(uint256 tournamentId, string memory reason) external onlyOwner {
        Tournament storage t = tournaments[tournamentId];
        require(t.exists, "TournamentPool: Does not exist");
        require(t.status == TournamentStatus.Open || t.status == TournamentStatus.Locked, "TournamentPool: Cannot cancel");

        t.status = TournamentStatus.Cancelled;
        emit TournamentCancelled(tournamentId, reason);
    }

    /**
     * @notice Claim full refund if contest is cancelled
     */
    function claimRefund(uint256 tournamentId) external nonReentrant {
        Tournament storage t = tournaments[tournamentId];
        require(t.status == TournamentStatus.Cancelled, "TournamentPool: Contest not cancelled");
        require(hasJoined[tournamentId][msg.sender], "TournamentPool: User did not join");

        Participant[] storage pList = _participants[tournamentId];
        bool found = false;
        for (uint256 i = 0; i < pList.length; i++) {
            if (pList[i].user == msg.sender) {
                require(!pList[i].refunded, "TournamentPool: Already refunded");
                pList[i].refunded = true;
                found = true;
                break;
            }
        }
        require(found, "TournamentPool: Participant not found");

        if (t.entryFee > 0) {
            bool refundSuccess = cricToken.transfer(msg.sender, t.entryFee);
            require(refundSuccess, "TournamentPool: Refund transfer failed");
        }

        emit EntryFeeRefunded(tournamentId, msg.sender, t.entryFee);
    }

    /**
     * @notice Get all participant addresses in a tournament
     */
    function getParticipants(uint256 tournamentId) external view returns (address[] memory) {
        Participant[] memory list = _participants[tournamentId];
        address[] memory users = new address[](list.length);
        for (uint256 i = 0; i < list.length; i++) {
            users[i] = list[i].user;
        }
        return users;
    }

    /**
     * @notice Get total participant count
     */
    function getParticipantCount(uint256 tournamentId) external view returns (uint256) {
        return _participants[tournamentId].length;
    }
}

